<script>
	$state(count = 0);

	function increment() {
		count++;
	}

	function decrement() {
		count--;
	}
</script>

<div class="counter">
	<button data-testid="decrement-button" on:click={decrement}>-</button>
	<span data-testid="count-value">{$state(count)}</span>
	<button data-testid="increment-button" on:click={increment}>+</button>
</div>
