<script>
	let count = $state(5);
	let doubled = $derived(count * 2);

	const increment = () => {
		count++;
	};
</script>

<div>
	<p data-testid="number-value">Number: {count}</p>
	<p data-testid="doubled-value">Doubled: {doubled}</p>
	<button data-testid="increment-button" on:click={increment}>Increment</button>
</div>
